import pandas as pd

def find_missing_ids(customers: pd.DataFrame) -> pd.DataFrame:
    if customers.empty:
        return pd.DataFrame({'ids': []})
    max_id = customers['customer_id'].max()
    full_seq = pd.DataFrame({'ids': list(range(1, max_id + 1))})
    missing = full_seq[~full_seq['ids'].isin(customers['customer_id'])]
    return missing.sort_values(by='ids')
